"""
MzoamBase
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.gnb.oam.megazone_client.interface import megazone_client
from taf.ul.trs_e2e_fw.lib.oam.exceptions import SiteConnectionError
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class MzoamBaseClass(object):
    """
    MzoamBaseClass
    """
    def __init__(self):
        self.mzom_client = megazone_client()
        self.protocol = "https"
        self.base_url = "{}://".format(self.protocol)
        self.config = ConfigHandler.get_config()

    def setup_oamops(self, **kwargs):
        """
        Function to setup oamops
        """
        alias = kwargs.get("alias", "default")
        if alias not in list(global_vars.alias_dut_dict.keys()):
            dut = kwargs.get("dut", "bts")
            connection_timeout = kwargs.get("timeout") or 60
            connection_retry_interval = kwargs.get("update_interval") or 1.0
            self.check_for_ignore_args(**kwargs)
            bts_host, bts_port, username, password = self._get_bts_params(**kwargs)
            # bts_host = self._format_ipv6_ipaddress(bts_host)
            url = self.base_url + "{}/".format(bts_host)
            if not self.mzom_client.wait_for_site_availability(url, connection_timeout,
                                                               interval=connection_retry_interval):
                raise SiteConnectionError(
                    "Could not connect to {} after {} seconds".format(url, connection_timeout))
            # TBD: Chained access to be checked
            logger.info("Connecting to {}".format(url))
            self.mzom_client.create_session(url, user=username, password=password, port=bts_port,
                                            alias=alias)
            global_vars.alias_dut_dict[alias] = dut
            try:
                sw_info = self.get_sw_versions(alias=alias)
                logger.info("\nBTS Software Information: {}".format(sw_info))
            except Exception as get_sw_version_error:
                logger.warn("Couldn't retrieve software version due to {}"
                            .format(get_sw_version_error))

        elif kwargs.get("execute_through_interface", False):
            raise Exception("Alias {} exists already. Create new alias".format(alias))
        else:
            logger.info("Skipping Setup Oamops for alias {}".format(alias))

    @staticmethod
    def _get_bts_params(**kwargs):
        dut = kwargs.get("dut", "bts")
        bts_host = kwargs.get('bts_host', get_config_variable([dut, 'ip']))
        bts_port = kwargs.get('admin_port', get_config_variable([dut, 'admin_port']))
        username = kwargs.get('admin_user', get_config_variable([dut, 'admin_user']))
        password = kwargs.get('admin_password', get_config_variable([dut, 'admin_password']))
        return bts_host, bts_port, username, password

    @staticmethod
    def check_for_ignore_args(**kwargs):
        """
        Function to check for ignore args
        """
        ignore_list = kwargs.get("ignore_list") or ["use_ssl", "admin_api_log_dir"]
        for key in ignore_list:
            if kwargs.get(key) is not None:
                logger.warn("Argument {} is not applicable for Mzaom, hence ignoring argument!!"
                            .format(key))

    def teardown_oamops(self, **kwargs):
        """
        Teardown oamops
        """
        all_alias = kwargs.get("all_alias", False)
        alias = kwargs.get("alias", "default")
        if all_alias:
            for alias in list(global_vars.alias_dut_dict.keys()):
                self.mzom_client.teardown_session(session=alias)
            global_vars.alias_dut_dict = {}
        else:
            self.mzom_client.teardown_session(session=alias)
            del global_vars.alias_dut_dict[alias]
        global_vars.setup_admin_called = False

    def get_sw_versions(self, **kwargs):
        """
        Function to get software versions
        """
        return self.mzom_client.get_sw_version(session=kwargs.get("alias", "default"))
